#include <Winsock2.h>
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int main() {
    /*
      Create a Winsock address to connect to the weather website
    */
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr("www.weather.com");
    addr.sin_port = htons(80);

    /*
      Create a socket to connect to the weather website
    */
    SOCKET sock = socket(AF_INET, SOCK_STREAM, 0);

    /*
      Connect to the weather website
    */
    connect(sock, (struct sockaddr *)&addr, sizeof(addr));

    /*
      Send the request to the weather website
    */
    ostringstream request;
    request << "GET / HTTP/1.1\r\n";
    request << "Host: www.weather.com\r\n";
    request << "Connection: close\r\n";
    request << "\r\n";

    send(sock, request.str().c_str(), request.str().length(), 0);

    /*
      Read the response from the weather website
    */
    char buf[1024] = { 0 };
    int len = recv(sock, buf, 1024, 0);

    /*
      Parse the response from the weather website
    */
    string response(buf);
    string line;

    while (getline(istringstream(response), line)) {
        if (line.find("Rainy") != string::npos) {
            istringstream iss(line);
            string word;

            while (iss >> word) {
                if (word == "Rainy") {
                    cout << "The weather forecast for Tuesday is Rainy" << endl;
                }
            }
        }
    }

    /*
      Close the socket
    */
    closesocket(sock);
    WSACleanup();

    return 0;
}
